// SPDX-License-Identifier: MIT
//! The four conformance tables, over the shared `text_bid_dpd` corpus.
//!
//! The vectors are read straight out of `resources/text_bid_dpd` — the
//! `decimal128-resources` submodule — and were generated by the `decimal128-c`
//! engine through its public API. That engine reaches its answers by different
//! algorithms than this codec does, so agreement is a cross-check rather than a
//! tautology.
//!
//!   T1 DECODE  bid -> text and dpd -> text          (100, noncanonical)
//!   T2 ENCODE  text -> bid and text -> dpd          (100)
//!   T3 PARSE   input text -> bits, both formats     (parse, 1,061 rows)
//!   T4 ERROR   malformed input text -> rejection    (error, 173 rows)
//!
//! Plus the cross-format assertion: for every row both encodings must render to
//! the same text. That is the strongest property the corpus encodes.
//!
//! The fifth table, `canonical`, is 84,783 rows of mostly common-path volume and
//! runs as the last test in this file.
//!
//! This suite is its own module — build.zig gives it the codec as an import, not
//! as a root — so it reaches only the public surface, the same black-box
//! arrangement the Go and Rust ports get from an external test package.

const std = @import("std");
const codec = @import("decimal128_text_codec");

// ---------------------------------------------------------------------------
// The tables
// ---------------------------------------------------------------------------

// T1: every row's two encodings must render to the expected text.
test "hundred decodes" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const rows = try loadCorpus(arena.allocator(), HUNDRED);
    try assertRowCount(rows, 100, HUNDRED);
    try runDecodeTable(rows, "100");
}

// T2: and the text must encode back to the same bits.
test "hundred re-encodes" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const rows = try loadCorpus(arena.allocator(), HUNDRED);
    try assertRowCount(rows, 100, HUNDRED);
    try runEncodeTable(rows, "100");
}

// One-way rows: both encodings decode to the text, but at least one is a bit
// pattern the canonical encoder would never emit, so re-encoding is
// deliberately not asserted.
test "non-canonical encodings render correctly" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const rows = try loadCorpus(arena.allocator(), NON_CANONICAL);
    try assertRowCount(rows, 1267, NON_CANONICAL);
    try runDecodeTable(rows, "noncanonical");
}

// T3: the only table that reaches the rounding surface at all.
test "parse vectors produce both encodings" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const rows = try loadCorpus(arena.allocator(), PARSE);
    try assertRowCount(rows, 1061, PARSE);
    for (rows) |row| {
        var bid: u128 = undefined;
        if (codec.bid128Parse(&bid, row.text)) |e| {
            std.debug.print("parse line {d}: bid rejected <{s}>: {s}\n", .{ row.line_number, row.text, e });
            return error.TestFailed;
        }
        if (bid != row.bid) {
            std.debug.print("parse line {d}: bid <{s}> gave {X:0>32}, expected {X:0>32}\n", .{ row.line_number, row.text, bid, row.bid });
            return error.TestFailed;
        }
        var dpd: u128 = undefined;
        if (codec.dpd128Parse(&dpd, row.text)) |e| {
            std.debug.print("parse line {d}: dpd rejected <{s}>: {s}\n", .{ row.line_number, row.text, e });
            return error.TestFailed;
        }
        if (dpd != row.dpd) {
            std.debug.print("parse line {d}: dpd <{s}> gave {X:0>32}, expected {X:0>32}\n", .{ row.line_number, row.text, dpd, row.dpd });
            return error.TestFailed;
        }
    }
}

// T4: malformed input. Both formats must reject, must agree on the reason, and
// must leave the canonical positive quiet NaN in the out-parameter — which is
// why the corpus carries that pattern in the bits columns of this table. The
// bits check runs against `row.bid` on both formats, exactly as the siblings
// do, and the `qnan` constant is checked against the same column so that a
// caller naming the constant and a caller reading a failed parse are known to
// see one pattern.
test "error vectors are rejected by both formats" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const rows = try loadCorpus(arena.allocator(), ERROR);
    try assertRowCount(rows, 173, ERROR);
    for (rows) |row| {
        var bid: u128 = undefined;
        var dpd: u128 = undefined;
        const bid_err = codec.bid128Parse(&bid, row.text);
        const dpd_err = codec.dpd128Parse(&dpd, row.text);
        if (bid_err == null) {
            std.debug.print("error line {d}: bid ACCEPTED <{s}>, corpus says {s}\n", .{ row.line_number, row.text, row.status });
            return error.TestFailed;
        }
        if (dpd_err == null) {
            std.debug.print("error line {d}: dpd ACCEPTED <{s}>, corpus says {s}\n", .{ row.line_number, row.text, row.status });
            return error.TestFailed;
        }
        if (!std.mem.eql(u8, bid_err.?, dpd_err.?)) {
            std.debug.print("error line {d}: the formats disagree on <{s}>: <{s}> vs <{s}>\n", .{ row.line_number, row.text, bid_err.?, dpd_err.? });
            return error.TestFailed;
        }
        if (bid != row.bid) {
            std.debug.print("error line {d}: bid <{s}> left {X:0>32}, expected {X:0>32}\n", .{ row.line_number, row.text, bid, row.bid });
            return error.TestFailed;
        }
        if (dpd != row.bid) {
            std.debug.print("error line {d}: dpd <{s}> left {X:0>32}, expected {X:0>32}\n", .{ row.line_number, row.text, dpd, row.bid });
            return error.TestFailed;
        }
        if (codec.qnan != row.bid) {
            std.debug.print("error line {d}: the corpus failure pattern is {X:0>32}, but qnan is {X:0>32}\n", .{ row.line_number, row.bid, codec.qnan });
            return error.TestFailed;
        }
    }
}

// The reader itself. `parse` and `error` quote their text column, and the four
// rows below are exactly the ones a naive comma split corrupts while still
// passing — a mangled malformed input fails to parse either way.
test "quoted column round trips" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const rows = try loadCorpus(arena.allocator(), ERROR);
    var has_empty = false;
    var has_leading_space = false;
    var has_trailing_space = false;
    var has_comma = false;
    for (rows) |row| {
        if (row.text.len == 0) has_empty = true;
        if (row.text.len > 0 and row.text[0] == ' ') has_leading_space = true;
        if (row.text.len > 0 and row.text[row.text.len - 1] == ' ') has_trailing_space = true;
        if (std.mem.indexOfScalar(u8, row.text, ',') != null) has_comma = true;
    }
    if (!has_empty) {
        std.debug.print("the empty-string row was lost\n", .{});
        return error.TestFailed;
    }
    if (!has_leading_space) {
        std.debug.print("a leading-space row was lost\n", .{});
        return error.TestFailed;
    }
    if (!has_trailing_space) {
        std.debug.print("a trailing-space row was lost\n", .{});
        return error.TestFailed;
    }
    if (!has_comma) {
        std.debug.print("an embedded-comma row was lost\n", .{});
        return error.TestFailed;
    }
}

// The full canonical table, read from the same submodule as the rest. It is a
// test of its own only because it is two orders of magnitude bigger than the
// other four put together, not because it is optional.
test "canonical table decodes and re-encodes" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const rows = try loadCorpus(arena.allocator(), CANONICAL);
    try assertRowCount(rows, 84783, CANONICAL);
    try runDecodeTable(rows, "canonical");
    try runEncodeTable(rows, "canonical");
}

// ---------------------------------------------------------------------------
// The two table runners
// ---------------------------------------------------------------------------

/// Every row: both encodings must render to the expected text, and therefore to
/// each other.
fn runDecodeTable(rows: []const CorpusRow, label: []const u8) !void {
    var buf: [codec.max_len]u8 = undefined;
    for (rows) |row| {
        const bid_text = codec.bid128ToAscii(&buf, row.bid);
        if (!std.mem.eql(u8, bid_text, row.text)) {
            std.debug.print("{s} line {d}: bid #{X:0>32} rendered <{s}>, expected <{s}>\n", .{ label, row.line_number, row.bid, bid_text, row.text });
            return error.TestFailed;
        }
        const dpd_text = codec.dpd128ToAscii(&buf, row.dpd);
        if (!std.mem.eql(u8, dpd_text, row.text)) {
            std.debug.print("{s} line {d}: dpd #{X:0>32} rendered <{s}>, expected <{s}>\n", .{ label, row.line_number, row.dpd, dpd_text, row.text });
            return error.TestFailed;
        }
    }
}

/// Round-trippable rows: the text must encode back to the same bits.
fn runEncodeTable(rows: []const CorpusRow, label: []const u8) !void {
    for (rows) |row| {
        var bid: u128 = undefined;
        if (codec.bid128Parse(&bid, row.text)) |e| {
            std.debug.print("{s} line {d}: bid rejected <{s}>: {s}\n", .{ label, row.line_number, row.text, e });
            return error.TestFailed;
        }
        if (bid != row.bid) {
            std.debug.print("{s} line {d}: bid <{s}> gave {X:0>32}, expected {X:0>32}\n", .{ label, row.line_number, row.text, bid, row.bid });
            return error.TestFailed;
        }
        var dpd: u128 = undefined;
        if (codec.dpd128Parse(&dpd, row.text)) |e| {
            std.debug.print("{s} line {d}: dpd rejected <{s}>: {s}\n", .{ label, row.line_number, row.text, e });
            return error.TestFailed;
        }
        if (dpd != row.dpd) {
            std.debug.print("{s} line {d}: dpd <{s}> gave {X:0>32}, expected {X:0>32}\n", .{ label, row.line_number, row.text, dpd, row.dpd });
            return error.TestFailed;
        }
    }
}

// ---------------------------------------------------------------------------
// One row of a text_bid_dpd table: the text, the two encodings, and the status
// column the input-driven tables carry.
// ---------------------------------------------------------------------------

const CorpusRow = struct {
    text: []const u8,
    bid: u128,
    dpd: u128,
    status: []const u8,
    line_number: usize,
};

/// Parse 32 hex digits, with or without a leading 0x.
fn parseHex32(s: []const u8) ?u128 {
    var body = s;
    if (std.mem.startsWith(u8, body, "0x") or std.mem.startsWith(u8, body, "0X")) body = body[2..];
    if (body.len != 32) return null;
    return std.fmt.parseInt(u128, body, 16) catch null;
}

// ---------------------------------------------------------------------------
// The shared conformance corpus, read from resources/text_bid_dpd — the
// decimal128-resources submodule, mounted at the repo root the way every
// decimal128 port mounts it. Nothing is copied into this repo.
//
// The row counts are asserted by the tests, and that is not ceremony: the text
// column of `parse` and `error` is double-quoted with backslash escapes, because
// those tables must carry the empty string, a leading and a trailing space, an
// embedded comma, an embedded quote and an embedded backslash. The other three
// leave it bare. A naive comma split silently corrupts four rows and still
// passes, since a mangled malformed input fails to parse either way. The row
// count is what catches it.
//
// build.zig runs the test binary with its cwd set to the project root, so the
// relative path below resolves the same way the full decimal128-zig port's
// rosetta corpus does. This is the one port with NO DECIMAL128_RESOURCES
// override: the siblings need one because their runners relocate the test
// binary away from the tree it was built in, and `zig build test` pins the
// working directory instead. Reading an environment variable in Zig 0.16 also
// costs a platform split -- getPosix / getWindows on a std.process.Environ --
// for a knob nothing here would turn.
// ---------------------------------------------------------------------------

const HUNDRED = "text_bid128_dpd128_100";
const NON_CANONICAL = "text_bid128_dpd128_noncanonical";
const PARSE = "text_bid128_dpd128_parse";
const ERROR = "text_bid128_dpd128_error";
const CANONICAL = "text_bid128_dpd128_canonical";

const MAX_FILE: usize = 32 * 1024 * 1024;

/// Where the loader looked, for a failure message that names the fix.
const RESOURCES_HINT = "the decimal128-resources submodule is not checked out: " ++
    "run `git submodule update --init --recursive`";

fn corpusPath(a: std.mem.Allocator, name: []const u8) ![]const u8 {
    return std.fmt.allocPrint(a, "resources/text_bid_dpd/{s}.csv.txt", .{name});
}

/// One table, read off the filesystem and parsed into rows.
fn loadCorpus(a: std.mem.Allocator, name: []const u8) ![]const CorpusRow {
    const path = try corpusPath(a, name);
    var threaded: std.Io.Threaded = .init(a, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const contents = std.Io.Dir.cwd().readFileAlloc(io, path, a, .limited(MAX_FILE)) catch |e| {
        std.debug.print("{s} could not be read ({s}) -- {s}\n", .{ path, @errorName(e), RESOURCES_HINT });
        return error.TestFailed;
    };
    return parseTable(a, contents, name);
}

fn assertRowCount(rows: []const CorpusRow, want: usize, name: []const u8) !void {
    if (rows.len != want) {
        std.debug.print("{s}.csv.txt has {d} rows, expected {d}\n", .{ name, rows.len, want });
        return error.TestFailed;
    }
}

fn parseTable(a: std.mem.Allocator, contents: []const u8, name: []const u8) ![]const CorpusRow {
    var rows: std.ArrayList(CorpusRow) = .empty;
    var line_number: usize = 0;
    var it = std.mem.splitScalar(u8, contents, '\n');
    while (it.next()) |raw_line| {
        line_number += 1;
        const line = skipSpace(std.mem.trimEnd(u8, raw_line, "\r"));
        if (line.len == 0 or line[0] == '#') continue;

        var text: []const u8 = undefined;
        var rest: []const u8 = undefined;
        if (line[0] == '"') {
            text, rest = try readQuoted(a, line);
        } else {
            text, rest = readField(line);
        }
        const bid_field, const after_bid = readNextField(rest);
        const dpd_field, const after_dpd = readNextField(after_bid);
        const status, _ = readNextField(after_dpd);

        const bid = parseHex32(bid_field);
        const dpd = parseHex32(dpd_field);
        if (bid == null or dpd == null) {
            std.debug.print("{s}.csv.txt line {d}: malformed hex columns <{s}> <{s}>\n", .{ name, line_number, bid_field, dpd_field });
            return error.TestFailed;
        }
        try rows.append(a, .{
            .text = text,
            .bid = bid.?,
            .dpd = dpd.?,
            .status = status,
            .line_number = line_number,
        });
    }
    return rows.items;
}

// -- the reader, matching the C, Swift, Kotlin, Java, C#, Go and Rust ports ---

fn skipSpace(s: []const u8) []const u8 {
    var i: usize = 0;
    while (i < s.len and (s[i] == ' ' or s[i] == '\t')) i += 1;
    return s[i..];
}

/// One comma-delimited field, stopping at ',' or '#' or end of line, with
/// surrounding whitespace trimmed. Returns the field and the unconsumed rest.
fn readField(s: []const u8) struct { []const u8, []const u8 } {
    const start = skipSpace(s);
    var end: usize = 0;
    while (end < start.len and start[end] != ',' and start[end] != '#') end += 1;
    var trim = end;
    while (trim > 0 and (start[trim - 1] == ' ' or start[trim - 1] == '\t')) trim -= 1;
    return .{ start[0..trim], start[end..] };
}

/// Step over a field separator, then read the next field. Yields the empty
/// string when the row has no further column.
fn readNextField(s: []const u8) struct { []const u8, []const u8 } {
    const rest = skipSpace(s);
    if (rest.len == 0 or rest[0] != ',') return .{ "", rest };
    return readField(rest[1..]);
}

/// The quoted text column, honouring backslash escapes.
fn readQuoted(a: std.mem.Allocator, s: []const u8) !struct { []const u8, []const u8 } {
    var out: std.ArrayList(u8) = .empty;
    var i: usize = 1; // past the opening quote
    while (i < s.len and s[i] != '"') {
        var c = s[i];
        i += 1;
        if (c == '\\' and i < s.len) {
            c = s[i];
            i += 1;
        }
        try out.append(a, c);
    }
    if (i < s.len and s[i] == '"') i += 1;
    return .{ out.items, s[i..] };
}
